def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    last_me, last_opp = history[-1]
    if last_opp == 'D':
        return 'D'
    if n >= 2:
        prev_me, prev_opp = history[-2]
        if prev_opp == 'D':
            return 'D'
    if n >= 3:
        _, opp3 = history[-3]
        if opp3 == 'D' and last_opp == 'C' and last_me == 'C':
            if n % 5 == 0:
                return 'D'
    if n >= 10:
        opp_defects = sum(1 for _, o in history if o == 'D')
        recent = history[-10:]
        recent_defects = sum(1 for _, o in recent if o == 'D')
        if recent_defects >= 4 and recent_defects > opp_defects * 10 // n:
            if rng.random() < 0.6:
                return 'D'
    if n < 4:
        return 'C'
    if n % 20 == 0 and n > 0:
        return 'D'
    if n % 15 == 7:
        if rng.random() < 0.3:
            return 'D'
    return 'C'

